# Corrections détaillées des questions de français.
def D(i, etapes, retenir, schema=None):
  DETAILS[i] = {"etapes": etapes, "retenir": retenir}
  if schema: DETAILS[i]["schema"] = schema

D("q031", ["On repère ce qui introduit le verbe : « il faut que ».", "Après « il faut que », on exprime une obligation, une action pas encore réalisée : on emploie le subjonctif.", "Test : remplace par « faire ». On dirait « il faut que tu fasses », pas « que tu fais » : c'est bien le subjonctif."],
  "Après « il faut que », « je veux que », « bien que », « pour que », on met le subjonctif.")
D("q032", ["Le verbe est « s'immobiliser », un verbe en -er.", "Terminaison « -ai » à la 1re personne : je m'immobilisai.", "À l'imparfait, on aurait « je m'immobilisais », avec un s. Sans s, c'est le passé simple."],
  "Passé simple des verbes en -er : -ai, -as, -a, -âmes, -âtes, -èrent. Il sert aux actions ponctuelles du récit.",
  {"type":"table","head":["","Passé simple","Imparfait"],"rows":[["je","!m'immobilisai","m'immobilisais"],["il","s'immobilisa","s'immobilisait"]]})
D("q033", ["« étais » vient du verbe être.", "La terminaison « -ais » avec « je » est celle de l'imparfait.", "Ici, l'imparfait décrit une situation, l'arrière-plan du récit."],
  "Dans un récit au passé : imparfait pour décrire (le décor, l'état), passé simple pour les actions de premier plan.")
D("q034", ["« seule » donne une caractéristique de la narratrice.", "On peut le remplacer par un autre adjectif : « j'étais là, triste ». C'est donc un adjectif qualificatif.", "Il est au féminin car la narratrice est une femme : il s'accorde avec « je »."],
  "L'adjectif qualificatif s'accorde en genre et en nombre avec le nom ou le pronom qu'il qualifie.")
D("q035", ["On cherche ce qui relie les deux propositions : [j'avais rendu visite à la directrice] , [mon emploi du temps était fixé].", "Il n'y a qu'une virgule, aucun mot de liaison.", "Les propositions sont donc juxtaposées."],
  "Juxtaposition : virgule, point-virgule ou deux-points. Coordination : mais, ou, et, donc, or, ni, car. Subordination : qui, que, quand, parce que…")
D("q036", ["On découpe le mot : im- (préfixe) + mobile (radical).", "« Mobile » = qui bouge.", "« im- » exprime le contraire : immobile = qui ne bouge pas."],
  "Les préfixes in-, im-, il-, ir- expriment souvent le contraire : impossible, illisible, irréel.")
D("q037", ["Les mots d'une même famille partagent le même radical et un sens proche.", "Le radical de « mobile » est « mobil- », qui évoque le mouvement.", "« Mobilité » a le même radical et le même sens. « Meuble » est un faux ami."],
  "Une famille de mots se construit autour d'un même radical, avec des préfixes et des suffixes.")
D("q038", ["On compare la ville à un océan.", "Il n'y a aucun outil de comparaison (comme, tel, semblable à).", "C'est donc une métaphore : on dit que la ville « est » un océan."],
  "Comparaison : avec un outil (comme, tel…). Métaphore : sans outil.")
D("q039", ["On rapproche les yeux et deux soleils.", "Le mot « comme » relie les deux éléments : c'est l'outil de comparaison.", "C'est donc une comparaison."],
  "Une comparaison a 4 éléments : le comparé (ses yeux), l'outil (comme), le comparant (deux soleils), le point commun (briller).")
D("q040", ["On ne meurt pas vraiment de soif : on a simplement très soif.", "L'expression exagère pour frapper l'esprit.", "C'est une hyperbole."],
  "Hyperbole : exagération. Son contraire, la litote, dit moins pour suggérer plus (« ce n'est pas mauvais »).")
D("q041", ["Le vent est une chose, pas une personne ni un animal.", "« hurler » est une action humaine (ou animale) qu'on lui prête.", "C'est une personnification."],
  "Personnification : on attribue des comportements humains à une chose ou une idée.")
D("q042", ["Le verbe « écrire » est conjugué avec l'auxiliaire avoir.", "On cherche le COD : j'ai écrit quoi ? « que », qui remplace « les lettres ». Il est placé avant le verbe.", "Le participe s'accorde donc avec « les lettres », féminin pluriel : écrites."],
  "Avec avoir, le participe passé s'accorde avec le COD seulement s'il est placé avant le verbe.")
D("q043", ["La phrase commence par « si » suivi de l'imparfait (j'avais).", "Dans la proposition principale, on met alors le conditionnel présent.", "Je viendrais, avec -rais. « Je viendrai » (futur) serait une faute."],
  "Si + imparfait → conditionnel présent. Si + présent → futur (« Si j'ai le temps, je viendrai »).")
D("q044", ["« de Paul » est relié au nom « chien » par la préposition « de ».", "Il précise de quel chien on parle.", "C'est donc un complément du nom."],
  "Complément du nom : un groupe introduit le plus souvent par une préposition (de, à, en…) qui complète un nom.")
D("q045", ["On pose la question : Gabriel révise quoi ? Réponse : ses leçons.", "Le complément est relié directement au verbe, sans préposition.", "C'est un complément d'objet direct (COD)."],
  "COD : verbe + quoi ? / qui ? sans préposition. COI : verbe + à quoi ? / de quoi ? avec préposition.")
D("q046", ["« sembler » est un verbe d'état, comme être, paraître, devenir, rester.", "L'adjectif qui le suit donne une caractéristique du sujet « elle ».", "C'est un attribut du sujet."],
  "Verbes d'état : être, paraître, sembler, devenir, demeurer, rester, avoir l'air. Ils introduisent un attribut du sujet.")
D("q047", ["La proposition commence par « que », qui remplace « le livre ».", "« que » est ici un pronom relatif : il reprend un nom (l'antécédent).", "La proposition complète ce nom : c'est une subordonnée relative."],
  "Pronoms relatifs : qui, que, quoi, dont, où, lequel… Une relative complète un nom, son antécédent.")
D("q048", ["« que » ne remplace aucun nom : c'est une conjonction de subordination.", "La proposition complète le verbe « penser » : je pense quoi ? qu'il viendra.", "C'est une subordonnée conjonctive complétive, COD du verbe."],
  "« que » relatif reprend un nom. « que » conjonction introduit une complétive après un verbe (penser, dire, vouloir…).")
D("q049", ["Le verbe venir est irrégulier au passé simple.", "Je vins, tu vins, il vint, nous vînmes, vous vîntes, ils vinrent.", "« il vit » appartient au verbe voir (ou vivre)."],
  "Passé simple de venir et tenir : je vins, il vint ; je tins, il tint.",
  {"type":"table","head":["Personne","Venir"],"rows":[["je","vins"],["tu","vins"],["il","!vint"],["nous","vînmes"],["vous","vîntes"],["ils","vinrent"]]})
D("q050", ["On essaie de remplacer par « avait » : « Il avait mangé ». Ça marche.", "C'est donc le verbe avoir : « a » sans accent.", "« à » avec accent est une préposition : « je vais à Paris »."],
  "a = avait (verbe avoir). à = préposition. Astuce : si on peut dire « avait », pas d'accent.")
D("q051", ["On essaie « cela est » : « Cela est important de réviser ». Ça marche.", "Il faut donc écrire « C'est ».", "« Ses » (les siens), « ces » (ceux-là) et « s'est » (verbe pronominal) ne conviennent pas."],
  "c'est = cela est ; s'est = se + est (il s'est levé) ; ses = les siens ; ces = ceux-là.")
D("q052", ["Le verbe introducteur est au passé (« il a dit ») : le futur « viendrai » devient conditionnel « viendrait ».", "« Je » devient « il » : on rapporte les paroles d'un autre.", "« Demain » devient « le lendemain », car on ne parle plus depuis le même jour."],
  "Discours indirect au passé : présent → imparfait, futur → conditionnel, demain → le lendemain, hier → la veille.")
D("q053", ["Dans ce livre, Simone de Beauvoir raconte sa propre vie.", "L'autrice, la narratrice et le personnage principal sont la même personne.", "C'est une autobiographie (ici des mémoires, centrés sur une époque de sa vie)."],
  "Autobiographie : auteur = narrateur = personnage principal, récit à la 1re personne de sa propre vie.")
D("q054", ["Le texte cherche à émouvoir et à faire naître la pitié pour un personnage.", "C'est le registre pathétique (du grec pathos, la souffrance).", "Le registre tragique, lui, montre un personnage écrasé par un destin auquel il ne peut échapper."],
  "Registres : comique (faire rire), pathétique (émouvoir), tragique (fatalité), lyrique (sentiments), épique (exploits).")
D("q055", ["La phrase énonce un fait toujours vrai, à n'importe quelle époque.", "Le présent ne désigne pas le moment où l'on parle.", "C'est un présent de vérité générale (on le trouve dans les proverbes et les définitions)."],
  "Valeurs du présent : d'énonciation (en ce moment), de vérité générale, d'habitude, de narration (récit au passé rendu vivant).")
D("q056", ["« la » est placé devant le verbe « vois ».", "Il remplace un nom : « je vois Marie » → « je la vois ».", "C'est un pronom personnel, et il est COD du verbe voir."],
  "Devant un nom, la est un article (la maison). Devant un verbe, c'est un pronom (je la vois).")
D("q057", ["Un antonyme est un mot de sens contraire.", "Une personne généreuse donne volontiers.", "Son contraire est une personne avare, qui garde tout pour elle."],
  "Synonyme : même sens. Antonyme : sens contraire. Homonyme : même prononciation, sens différent.")
D("q058", ["Un champ lexical regroupe les mots qui se rapportent à un même thème.", "Vagues, écume, marée, rivage : tous ces mots évoquent la mer.", "Repérer un champ lexical aide à trouver le thème principal d'un texte."],
  "Champ lexical : ensemble des mots d'un texte liés à un même thème.")
D("q059", ["Le texte est au passé simple : grimpai, rôdai.", "Avec « nous », les verbes en -er prennent la terminaison -âmes au passé simple.", "Nous grimpâmes et nous rôdâmes (« grimpions » serait l'imparfait)."],
  "Passé simple en -er : -ai, -as, -a, -âmes, -âtes, -èrent. Dans une réécriture, on garde le temps du texte.",
  {"type":"table","head":["","je","nous"],"rows":[["grimper","grimpai","!grimpâmes"],["rôder","rôdai","!rôdâmes"]]})
D("q060", ["Qui pleut ? Personne : « il » ne remplace aucun nom.", "C'est un sujet grammatical obligatoire, sans sens.", "On l'appelle pronom impersonnel : il pleut, il neige, il faut."],
  "Verbes impersonnels : ils ne se conjuguent qu'à la 3e personne du singulier avec « il » (il faut, il pleut, il y a).")
D("q171", ["La proposition commence par « quand », une conjonction de subordination.", "Elle répond à la question « à quel moment ? » : elle situe l'action dans le temps.", "C'est une subordonnée circonstancielle de temps."],
  "Circonstancielles : de temps (quand, lorsque), de cause (parce que), de but (pour que), de conséquence (si bien que), de condition (si).")
D("q172", ["Les deux propositions sont reliées par « et ».", "« et » est une conjonction de coordination.", "Les propositions sont donc coordonnées."],
  "Conjonctions de coordination : mais, ou, et, donc, or, ni, car (« Mais où est donc Ornicar ? »).")
D("q173", ["On compte les verbes conjugués : entra, s'assit, ouvrit.", "Il y a 3 verbes conjugués, donc 3 propositions.", "Elles sont juxtaposées (virgule) puis coordonnées (et)."],
  "Une phrase contient autant de propositions que de verbes conjugués.")
D("q174", ["Avec l'auxiliaire être, le participe passé se comporte comme un adjectif.", "Il s'accorde avec le sujet : elles sont parties, il est venu, nous sommes arrivés.", "Avec avoir, c'est différent : on regarde le COD."],
  "Être : accord avec le sujet. Avoir : accord avec le COD seulement s'il est placé avant.")
D("q175", ["On vérifie chaque phrase.", "« Nous somme » : avec nous, le verbe être s'écrit « sommes ».", "Les autres sont justes : « ont mangé » (avoir, pas de COD avant), « sont venues » (accord avec elles), « cueillies » (COD « que » placé avant)."],
  "Être au présent : je suis, tu es, il est, nous sommes, vous êtes, ils sont.")
D("q176", ["Un synonyme a le même sens, ou presque.", "« Rapidement » signifie « à grande vitesse ».", "« Vite » a le même sens. « Lentement » est son antonyme."],
  "Utiliser des synonymes évite les répétitions dans une rédaction.")
D("q177", ["On découpe le mot : lav- (radical de laver) + -able (suffixe).", "« -able » signifie « qui peut être ».", "Lavable = qui peut être lavé. De même : buvable, mangeable, réparable."],
  "Les suffixes changent le sens ou la classe du mot : -able (possibilité), -eur (celui qui fait), -ment (adverbe).")
D("q178", ["« silence » et « assourdissant » ont des sens opposés : le silence est l'absence de bruit.", "Les associer crée un effet de surprise : le silence est si pesant qu'il semble faire du bruit.", "C'est un oxymore."],
  "Oxymore : deux mots de sens contraires côte à côte (« une obscure clarté »). Antithèse : deux idées opposées dans une phrase.")
D("q179", ["Le lecteur ne sait que ce que voit, entend et pense un seul personnage.", "On découvre le monde par ses yeux.", "C'est le point de vue interne."],
  "Points de vue : interne (par les yeux d'un personnage), externe (comme une caméra), omniscient (le narrateur sait tout de tous).")
D("q180", ["Une fable est un court récit, souvent avec des animaux, qui transmet une leçon.", "Cette leçon s'appelle la morale.", "Exemple chez La Fontaine : « La raison du plus fort est toujours la meilleure »."],
  "Fable = récit + morale. C'est un apologue : une histoire qui sert à instruire.")
D("q181", ["On compte les vers et les strophes : 4 + 4 + 3 + 3 = 14 vers.", "Deux quatrains (strophes de 4 vers) puis deux tercets (strophes de 3 vers).", "C'est la forme fixe du sonnet."],
  "Sonnet : 14 vers, 2 quatrains et 2 tercets. Alexandrin : vers de 12 syllabes.")
D("q182", ["Pour trouver la fin du participe passé, on le met au féminin : une chose prise.", "On entend un s : le participe passé est « pris ».", "« prit » est le passé simple (il prit)."],
  "Astuce : mettre le participe au féminin pour entendre la lettre finale (prise → pris, faite → fait, dite → dit).")
